// Implementation Core: Non-parametric Manipulator (e.g., std::boolalpha)

std::ios_base& boolalpha_impl(std::ios_base& str) {
    // Modify internal state flags
    str.setf(std::ios_base::boolalpha);
    return str; // Return modified stream reference
}

// Stream Operator Hook (Executed via << or >>)
// Overload matches function pointer signature: F(ios_base&) -> ios_base&

template <typename C, typename T>
std::basic_ostream<C, T>& 
operator<<(std::basic_ostream<C, T>& os,
           std::ios_base& (*pf)(std::ios_base&)) 
{
    pf(os); // Calls the manipulator function
    return os;
}
